CREATE TABLE IF NOT EXISTS tenants (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_users_tenant_id ON users(tenant_id);
CREATE TABLE IF NOT EXISTS scans (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, scan_type TEXT NOT NULL, target TEXT NOT NULL, status TEXT NOT NULL, verdict TEXT NOT NULL, risk_score INTEGER NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_scans_tenant_id ON scans(tenant_id);
CREATE TABLE IF NOT EXISTS iocs (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, kind TEXT NOT NULL, value TEXT NOT NULL, source_scan_id INTEGER NOT NULL, created_at TEXT NOT NULL);
